interface CartState { lines: Line[] }

class CartPage extends React.Component<{}, CartState> {
  state: CartState = { lines: [] };                 // typed state
  private unsub = () => {};
  componentDidMount() {
    this.unsub = store.subscribe(() => this.setState({ lines: store.lines }));
  }
  componentWillUnmount() { this.unsub(); }
  render() { return <CartLines lines={this.state.lines} />; }
}
